const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Travel']);

// --- FLIGHTS ONLY ---
const flights = data.filter(r => r.Type === 'Flight');
const confirmedFlights = flights.filter(r => r.Status === 'confirmed');
const cancelledFlights = flights.filter(r => r.Status === 'cancelled');

console.log('=== ROUTE FREQUENCY (All Flights) ===');
const routeCounts = {};
flights.forEach(r => { routeCounts[r['Route/Location']] = (routeCounts[r['Route/Location']] || 0) + 1; });
Object.entries(routeCounts).sort((a,b) => b[1]-a[1]).forEach(([r,c]) => console.log('  ' + r + ': ' + c));

console.log('\n=== CONFIRMED FLIGHT PRICES (non-zero) ===');
confirmedFlights.filter(r => r.Amount > 0).forEach(r =>
  console.log('  ' + r['Booking ID'] + ' | ' + r.User + ' | ' + r['Route/Location'] + ' | \$' + r.Amount)
);

console.log('\n=== PRICE STATS (confirmed, non-zero) ===');
const prices = confirmedFlights.filter(r => r.Amount > 0).map(r => r.Amount);
console.log('  Min: \$' + Math.min(...prices));
console.log('  Max: \$' + Math.max(...prices));
console.log('  Avg: \$' + Math.round(prices.reduce((a,b)=>a+b,0)/prices.length));
console.log('  Median: \$' + prices.sort((a,b)=>a-b)[Math.floor(prices.length/2)]);

console.log('\n=== AIRPORT FREQUENCY (departure) ===');
const depCounts = {};
flights.forEach(r => {
  const dep = r['Route/Location'].split('→')[0].trim();
  if (dep) depCounts[dep] = (depCounts[dep] || 0) + 1;
});
Object.entries(depCounts).sort((a,b) => b[1]-a[1]).forEach(([a,c]) => console.log('  ' + a + ': ' + c));

console.log('\n=== AIRPORT FREQUENCY (arrival) ===');
const arrCounts = {};
flights.forEach(r => {
  const parts = r['Route/Location'].split('→');
  const arr = parts.length > 1 ? parts[1].trim() : '';
  if (arr) arrCounts[arr] = (arrCounts[arr] || 0) + 1;
});
Object.entries(arrCounts).sort((a,b) => b[1]-a[1]).forEach(([a,c]) => console.log('  ' + a + ': ' + c));

console.log('\n=== HOTELS & CAR RENTALS (confirmed) - for cross-referencing ===');
data.filter(r => r.Type !== 'Flight' && r.Status === 'confirmed').forEach(r =>
  console.log('  ' + r.Type + ' | ' + r.User + ' | ' + r['Route/Location'] + ' | ' + r.Dates + ' | \$' + r.Amount)
);

console.log('\n=== DESTINATIONS WITH HOTEL BUT NO CONFIRMED FLIGHT ===');
const confirmedFlightDests = new Set(confirmedFlights.map(r => r['Route/Location'].split('→').pop().trim()));
const confirmedHotels = data.filter(r => r.Type === 'Hotel' && r.Status === 'confirmed');
confirmedHotels.forEach(h => {
  const city = h['Route/Location'].split(',').pop().trim();
  console.log('  Hotel in ' + city + ' (' + h.Dates + ') — flight to area airports needed?');
  console.log('    Relevant airports: ' + (city === 'Boston' ? 'BOS' : city === 'Las Vegas' ? 'LAS' : city === 'San Francisco' ? 'SFO' : '?'));
  console.log('    Matching confirmed flights to that airport: ' + confirmedFlights.filter(f => {
    const arr = f['Route/Location'].split('→').pop().trim();
    return (city === 'Boston' && arr === 'BOS') || (city === 'Las Vegas' && arr === 'LAS') || (city === 'San Francisco' && arr === 'SFO');
  }).map(f => f['Booking ID'] + '(' + f.User + ')').join(', '));
});
"

